package reference

import (
	"errors"
	"strings"
)

// ErrNoSchemaSection is returned when a page contains no schema section to
// replace (for example a hand-written template not using .SchemaMarkdown).
var ErrNoSchemaSection = errors.New("no schema section found")

// ReplaceSection replaces the schema section of a docs page by section. It
// accepts both the section generated by tfplugindocs and one previously
// generated by tfrefdoc, so running it twice is harmless.
func ReplaceSection(page, section string) (string, error) {
	if i := strings.Index(page, startMarker); i >= 0 {
		j := strings.Index(page[i:], endMarker)
		if j < 0 {
			return "", errors.New("start marker found without end marker")
		}
		end := i + j + len(endMarker)
		return page[:i] + strings.TrimSuffix(section, "\n") + page[end:], nil
	}

	i := strings.Index(page, tfplugindocsMarker)
	if i < 0 {
		return "", ErrNoSchemaSection
	}
	// The tfplugindocs section is the "## Schema" heading and everything up
	// to the next level-2 heading (often "## Import") or the end of file.
	body := i + len(tfplugindocsMarker)
	end := len(page)
	lines := strings.SplitAfter(page[body:], "\n")
	pos := body
	seenSchema := false
	for _, l := range lines {
		if strings.HasPrefix(l, "## ") {
			if seenSchema {
				end = pos
				break
			}
			seenSchema = true
		}
		pos += len(l)
	}
	rest := page[end:]
	out := page[:i] + section
	if rest != "" {
		out += "\n" + rest
	}
	return out, nil
}
